create table veranolink.vl_source_collections (
    id_vl_source_collection  number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    id_parent_collection     number,
    name_collection          varchar2(1000 char),
    id_vl_source_application number
);

alter table veranolink.vl_source_collections
    add constraint vl_source_collections_pk primary key ( id_vl_source_collection )
        using index enable;

